/**
 *
 * FieldsetIndicator is a component that displays an indicator inside a Fieldset.
 *
 * [Live Demo](https://www.primereact.org/fieldset/)
 *
 * @module FieldsetIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { FieldsetRootInstance } from './FieldsetRoot.types';
/**
 * Defines passthrough(pt) options type in FieldsetIndicator component.
 */
export type FieldsetIndicatorPassThroughType<E> = PassThroughType<FieldsetIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of FieldsetIndicator component.
 */
export interface FieldsetIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: FieldsetIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in FieldsetIndicator component.
 */
export interface FieldsetIndicatorProps extends BaseComponentProps<FieldsetIndicatorInstance, unknown, FieldsetIndicatorPassThrough> {
    /**
     * Determines the visibility of the indicator based on the state of the fieldset. Valid values are:
     * - "open": Indicator is visible when the fieldset is expanded.
     * - "closed": Indicator is visible when the fieldset is collapsed.
     * - "always": Indicator is always visible regardless of state.
     */
    match?: 'open' | 'closed' | 'always' | undefined;
}
/**
 * Defines valid state in FieldsetIndicator component.
 */
export interface FieldsetIndicatorState {
}
/**
 * Defines the methods and properties exposed by FieldsetIndicator component.
 */
export interface FieldsetIndicatorExposes {
    /**
     * The Fieldset component instance.
     */
    fieldset: FieldsetRootInstance | undefined | null;
}
/**
 * Instance of FieldsetIndicator component.
 */
export type FieldsetIndicatorInstance = ComponentInstance<FieldsetIndicatorProps, FieldsetIndicatorState, FieldsetIndicatorExposes>;
